%[text] # Motor Drive Unit - Simulation Case
%[text] ## Constant input signals
%[text] Check that the model runs out of the box.
model_name = "HarnessModel_MotorDriveUnit";
load_system(model_name)

setupHarness_MotorDriveUnit

set_param(model_name + "/Motor Drive Unit", ReferencedSubsystem = "MotorDriveUnit_SystemThermal_refsub")

set_param(model_name + "/Inputs", ReferencedSubsystem = "Inputs_MotorDriveUnit_Constant_refsub")

% Initial conditions
initial.LoadInertiaSpeed = simscape.Value(0, "rpm");
initial.motorDriveUnit_RotorSpd_rpm = 0;
initial.ambientTemp_K = motorDriveUnit.ambientTemp_K;

sim_in = Simulink.SimulationInput(model_name);
sim_in = setModelParameter(sim_in, StopTime = "400");
%[text] Run simulation.
sim_out = sim(sim_in);
%[text] Visually inspect the result.
sim_data = extractTimetable(sim_out.logsout);

% Signal logging names in the model.
signal_names = [
  "Motor torque command"
  "Axle torque input"
  "Motor power rate"
  "Motor speed"
  "Motor temperature"
  "Battery power"
  "Battery current"
  "Battery voltage"
  ];

for idx = 1 : numel(signal_names) %[output:group:32222b2c]
  fig = bevutil1.SignalUtil.plotTimedData(TimedData = sim_data, SignalName = signal_names(idx)); %[output:79edb0bb] %[output:2e3a3a8d] %[output:775db8d7] %[output:0f611f8c] %[output:6fc35569] %[output:545934ae] %[output:6d31ac30] %[output:8b6fa6ea]
  fig.Position(4) = 100;  % height
end %[output:group:32222b2c]
